2	using System.Collections.Generic;
3	
4	public abstract class BusBase
5	{
6	    readonly Dictionary<Type, Delegate> _handlers = new();
7	
8	    public void Send<T>(T data) where T : struct
9	    {
10	        if (_handlers.TryGetValue(typeof(T), out var d))
11	            ((Action<T>)d).Invoke(data);
12	    }
13	
14	    public void On<T>(Action<T> handler) where T : struct
15	    {
16	        var key = typeof(T);
17	        _handlers[key] = _handlers.TryGetValue(key, out var d)
18	            ? (Action<T>)d + handler
19	            : handler;
20	    }
21	
22	    public void Off<T>(Action<T> handler) where T : struct
23	    {
24	        var key = typeof(T);
25	        if (_handlers.TryGetValue(key, out var d))
26	            _handlers[key] = (Action<T>)d - handler;
27	    }
28	
29	    protected void Clear() => _handlers.Clear();
30	}
