1	using System;
2	using System.Collections.Generic;
3	using UnityEngine;
4	using VContainer;
5	
6	namespace Base
7	{
8	    /// <summary>
9	    /// State machine generic — dùng được với bất kỳ enum nào làm key state.
10	    /// State được resolve từ container, cache lại để tái sử dụng.
11	    /// Mọi state phải được đăng ký vào DI trước (trong Ctrl).
12	    /// </summary>
13	    public class StateMachine<TStateType> where TStateType : Enum
14	    {
15	        private readonly IObjectResolver container;
16	        private readonly Dictionary<Type, IState> stateCache;      // Cache state đã tạo để tránh tạo lại mỗi lần
17	        private readonly Dictionary<TStateType, Type> stateTypeMap; // Map enum value → System.Type của state
18	        private readonly EqualityComparer<TStateType> enumComparer; // Cache comparer, tránh boxing mỗi lần so sánh
19	
20	        private IState currentState;
21	
22	        public TStateType CurrentStateType { get; private set; }
23	
24	        public StateMachine(IObjectResolver container, Dictionary<TStateType, Type> stateTypeMap)
25	        {
26	            this.container = container;
27	            this.stateTypeMap = stateTypeMap;
28	            stateCache = new Dictionary<Type, IState>(stateTypeMap.Count);
29	            enumComparer = EqualityComparer<TStateType>.Default;
30	        }
31	
32	        /// <summary>
33	        /// Chuyển sang state mới: gọi Exit() state cũ, tạo/lấy cache state mới, gọi Enter().
34	        /// </summary>
35	        public void ChangeState(TStateType stateType, object data = null)
36	        {
37	            // Validate trước khi exit — tránh mất state nếu stateType không hợp lệ
38	            if (!stateTypeMap.TryGetValue(stateType, out Type type))
39	            {
40	                Debug.LogError($"State type not found: {stateType}");
41	                return;
42	            }
43	
44	            // Lấy từ cache hoặc resolve từ container
45	            if (!stateCache.TryGetValue(type, out IState state))
46	            {
47	                state = (IState)container.Resolve(type);
48	                stateCache[type] = state;
49	            }
50	
51	            currentState?.OnExit();
52	            currentState = state;
53	            CurrentStateType = stateType;
54	
55	            currentState.OnEnter(data);
56	        }
57	
58	        /// <summary>
59	        /// Gọi OnUpdate() của state hiện tại — đặt trong MonoBehaviour.Update().
60	        /// </summary>
61	        public void Update() => currentState?.OnUpdate();
62	
63	        /// <summary>
64	        /// Gọi OnFixedUpdate() của state hiện tại — đặt trong MonoBehaviour.FixedUpdate().
65	        /// </summary>
66	        public void FixedUpdate() => currentState?.OnFixedUpdate();
67	
68	        /// <summary>
69	        /// Gọi OnLateUpdate() của state hiện tại — đặt trong MonoBehaviour.LateUpdate().
70	        /// </summary>
71	        public void LateUpdate() => currentState?.OnLateUpdate();
72	
73	        /// <summary>
74	        /// Kiểm tra state machine có đang ở state chỉ định không.
75	        /// </summary>
76	        public bool IsInState(TStateType stateType)
77	        {
78	            return enumComparer.Equals(CurrentStateType, stateType);
79	        }
80	
81	        /// <summary>
82	        /// Gọi Exit() state hiện tại mà không chuyển sang state mới — dùng khi object bị destroy.
83	        /// </summary>
84	        public void ForceExit()
85	        {
86	            currentState?.OnExit();
87	            currentState = null;
88	        }
89	    }
90	}
