1	using System;
2	using System.Collections.Generic;
3	using VContainer;
4	using VContainer.Unity;
5	
6	namespace Base
7	{
8	    /// <summary>
9	    /// Base chung cho GameCtrlBase và SceneCtrlBase.
10	    /// Mỗi Ctrl (GameCtrl, HomeCtrl, GameplayCtrl) kế thừa một trong hai — không kế thừa trực tiếp CtrlBase.
11	    ///
12	    /// Mỗi Ctrl tự động làm 2 việc:
13	    ///   1. Khởi động StateMachine từ ConfigureStates() + InitialState
14	    ///   2. Gọi ConfigureDependencies() để đăng ký các dependency còn lại
15	    ///
16	    /// Mọi dependency — kể cả State — đều đăng ký trong ConfigureDependencies().
17	    /// Mở Ctrl là thấy hết scene cần gì.
18	    /// </summary>
19	    public abstract class CtrlBase<TStateType> : LifetimeScope
20	        where TStateType : Enum
21	    {
22	        private StateMachine<TStateType> _stateMachine;
23	        private Dictionary<TStateType, Type> _stateMap;
24	
25	        [UnityEngine.SerializeField] private TStateType _currentState;
26	        public TStateType CurrentState => _currentState;
27	
28	        /// <summary>State đầu tiên chạy khi scene/game khởi động.</summary>
29	        protected abstract TStateType InitialState { get; }
30	
31	        /// <summary>
32	        /// Khai báo các state của Ctrl. Gọi builder.Register&lt;XxxState&gt;(State.Xxx) cho từng state.
33	        /// </summary>
34	        protected abstract void ConfigureStates(StateMachineBuilder<TStateType> builder);
35	
36	        protected override void Configure(IContainerBuilder builder)
37	        {
38	            var smBuilder = new StateMachineBuilder<TStateType>();
39	            ConfigureStates(smBuilder);
40	            _stateMap = smBuilder.Build();
41	
42	            ConfigureDependencies(builder);
43	        }
44	
45	        /// <summary>
46	        /// Đăng ký tất cả dependency của scene ở đây: State, Service, MonoBehaviour, EventBus, v.v.
47	        /// </summary>
48	        protected virtual void ConfigureDependencies(IContainerBuilder builder) { }
49	
50	        private void Start()
51	        {
52	            _stateMachine = new StateMachine<TStateType>(Container, _stateMap);
53	            ChangeState(InitialState);
54	            OnStart();
55	        }
56	
57	        private void Update() => _stateMachine?.Update();
58	        private void FixedUpdate() => _stateMachine?.FixedUpdate();
59	        private void LateUpdate() => _stateMachine?.LateUpdate();
60	
61	        protected override void OnDestroy()
62	        {
63	            _stateMachine?.ForceExit();
64	            base.OnDestroy();
65	        }
66	
67	        public void ChangeState(TStateType state, object data = null)
68	        {
69	            _stateMachine.ChangeState(state, data);
70	            _currentState = state;
71	        }
72	
73	        public bool IsInState(TStateType state)
74	            => _stateMachine.IsInState(state);
75	
76	        /// <summary>
77	        /// Hook tùy chọn — override để chạy logic sau khi StateMachine đã khởi tạo xong.
78	        /// </summary>
79	        protected virtual void OnStart() { }
80	    }
81	}
