20	
21	## 2. Setup scene
22	
23	### Boot scene — GameCtrl
24	
25	```csharp
26	public class GameCtrl : GameCtrlBase<GameCtrl.State>
27	{
28	    public enum State { Boot, Home, Gameplay }
29	    protected override State InitialState => State.Boot;
30	
31	    protected override void ConfigureStates(StateMachineBuilder<State> builder)
32	    {
33	        builder.Register<BootState>(State.Boot);
34	        builder.Register<HomeState>(State.Home);
35	        builder.Register<GameplayFlowState>(State.Gameplay);
36	    }
37	
38	    protected override void ConfigureDependencies(IContainerBuilder builder)
39	    {
40	        builder.Register<BootState>(Lifetime.Singleton);
41	        builder.Register<HomeState>(Lifetime.Singleton);
42	        builder.Register<GameplayFlowState>(Lifetime.Singleton);
43	        // GameBus tự đăng ký — không cần thêm
