81	## 3. Viết State
82	
83	```csharp
84	public class PlayingState : StateBase
85	{
86	    [Inject] private Player _player;
87	    [Inject] private GameplayCtrl _ctrl;
88	    [Inject] private SceneBus _bus;
89	
90	    public override void OnEnter(object data = null)
91	    {
92	        _player.gameObject.SetActive(true);
93	        _bus.On<PlayerFellMessage>(OnPlayerFell);
94	    }
95	
96	    public override void OnExit()
97	    {
98	        _bus.Off<PlayerFellMessage>(OnPlayerFell);
99	    }
100	
101	    void OnPlayerFell(PlayerFellMessage _)
102	        => _ctrl.ChangeState(GameplayCtrl.State.Lose);
103	}
104	```
