3	/// <summary>
4	/// Reactive value — gán Value sẽ notify tất cả subscriber.
5	/// On() nhận giá trị hiện tại ngay khi đăng ký.
6	/// Off() để hủy — dùng trong OnDisable / OnExit.
7	/// </summary>
8	public class Value<T>
9	{
10	    T _value;
11	    event Action<T> _onChange;
12	
13	    public Value(T initial = default) => _value = initial;
14	
15	    public T Current
16	    {
17	        get => _value;
18	        set { _value = value; _onChange?.Invoke(value); }
19	    }
20	
21	    public void On(Action<T> handler)  { _onChange += handler; handler(_value); }
22	    public void Off(Action<T> handler) => _onChange -= handler;
23	}
