1	using System;
2	using Cysharp.Threading.Tasks;
3	using UnityEngine;
4	using UnityEngine.SceneManagement;
5	
6	namespace Base
7	{
8	    /// <summary>
9	    /// Quản lý load/unload scene bất đồng bộ
10	    /// </summary>
11	    public class SceneLoader
12	    {
13	        // Note: Event để update progress bar
14	        public static Action<float> OnProgressChanged;
15	
16	        /// <summary>
17	        /// Load scene bất đồng bộ (mượt mà)
18	        /// </summary>
19	        /// <param name="sceneName">Tên scene (phải có trong Build Settings)</param>
20	        /// <param name="mode">Single: Đóng scene cũ | Additive: Giữ scene cũ</param>
21	        /// <param name="minLoadTime">Thời gian load tối thiểu (giây) - để người chơi thấy loading</param>
22	        public static async UniTask LoadScene(string sceneName, LoadSceneMode mode = LoadSceneMode.Single,
23	            float minLoadTime = 0)
24	        {
25	            // Note: Dọn rác trước khi load để giảm lag
26	            CleanupMemory();
27	
28	            float startTime = Time.time;
29	
30	            // Note: Bắt đầu load scene
31	            var op = SceneManager.LoadSceneAsync(sceneName, mode);
32	
33	            if (op == null) return;
34	
35	            // Note: Không cho scene tự động activate
36	            op.allowSceneActivation = false;
37	
38	            // Note: Giảm priority để không làm đơ game
39	            Application.backgroundLoadingPriority = ThreadPriority.Low;
40	
41	            // Note: Chờ load đến 90%
42	            while (op.progress < 0.9f)
43	            {
44	                // Note: Progress từ 0 đến 0.9
45	                float progress = op.progress / 0.9f;
46	                OnProgressChanged?.Invoke(progress);
47	
48	                await UniTask.Yield();
49	            }
50	
51	            // Note: Đợi đủ minLoadTime (tránh loading quá nhanh)
52	            float elapsedTime = Time.time - startTime;
53	            if (elapsedTime < minLoadTime)
54	            {
55	                // ✅ SỬA: Tính toán đúng thời gian còn lại
56	                float targetTime = startTime + minLoadTime;
57	
58	                // Note: Fake progress từ 0.9 đến 1.0
59	                while (Time.time < targetTime)
60	                {
61	                    // ✅ Tính progress dựa trên thời gian thực tế
62	                    float currentTime = Time.time - startTime;
63	                    float fakeProgress = Mathf.Lerp(0.9f, 1f, currentTime / minLoadTime);
64	                    OnProgressChanged?.Invoke(Mathf.Clamp01(fakeProgress));
65	
66	                    await UniTask.Yield();
67	                }
68	            }
69	
70	            // Note: Set progress = 1
71	            OnProgressChanged?.Invoke(1f);
72	
73	            // Note: Activate scene
74	            op.allowSceneActivation = true;
75	
76	            // Note: Đợi scene activate xong
77	            while (!op.isDone)
78	            {
79	                await UniTask.Yield();
80	            }
81	
82	            // Note: Khôi phục priority về mặc định
83	            Application.backgroundLoadingPriority = ThreadPriority.Normal;
84	        }
85	
86	        /// <summary>
87	        /// Dọn memory trước khi load scene
88	        /// </summary>
89	        private static void CleanupMemory()
90	        {
91	            // Note: Giải phóng tài nguyên không dùng
92	            Resources.UnloadUnusedAssets();
93	
94	            // Note: Chạy Garbage Collector
95	            GC.Collect();
96	
97	            Debug.Log("[SceneLoader] Đã dọn memory");
98	        }
99	
100	        /// <summary>
101	        /// Unload scene (chỉ dùng cho Additive mode)
102	        /// </summary>
103	        /// <param name="sceneName">Tên scene cần unload</param>
104	        public static async UniTask UnloadScene(string sceneName)
105	        {
106	            // Note: Unload scene và giải phóng memory
107	            var op = SceneManager.UnloadSceneAsync(sceneName);
108	
109	            // Note: Chờ unload xong
110	            while (op != null && !op.isDone)
111	            {
112	                await UniTask.Yield();
113	            }
114	
115	            // Note: Dọn memory sau khi unload
116	            CleanupMemory();
117	        }
118	
119	        /// <summary>
120	        /// Unload scene (chỉ dùng cho Additive mode)
121	        /// </summary>
122	        public static async UniTask UnloadScene(Scene scene)
123	        {
124	            // Note: Unload scene và giải phóng memory
125	            var op = SceneManager.UnloadSceneAsync(scene);
126	
127	            // Note: Chờ unload xong
128	            while (op != null && !op.isDone)
129	            {
130	                await UniTask.Yield();
131	            }
132	
133	            // Note: Dọn memory sau khi unload
134	            CleanupMemory();
135	        }
136	    }
137	}

